    """Predicate at KernelWriterAssembly.py:7475 (closeLoop): tailLoop = (loopIdx < 0).

    post: __return__ == (loopIdx < 0)
    """
    tailLoop = loopIdx < 0
    return tailLoop


def loopidx_to_tail(no_tail_loop: bool, tailloop_in_nll: bool, is_normal_unroll_close: bool) -> bool:
    """Composition: YAML gates -> call-site loopIdx -> tailLoop branch.

    post: __return__ == ((not is_normal_unroll_close) and (tailloop_in_nll or (not no_tail_loop)))
    """
    if is_normal_unroll_close:
        loopIdx = 0
    elif tailloop_in_nll:
        loopIdx = -2
    elif not no_tail_loop:
        loopIdx = -1
    else:
        loopIdx = 0
    return loopIdx < 0
